.wsleakbrief__red4:not(.wsleakbrief__pog)>div{background:#fff;border:1px solid rgba(233,166,182,.35);border-radius:16px;padding:24px 16px;box-shadow:0 6px 18px rgba(0,0,0,.05)}.wsleakbrief__red3 span.wsleakbrief__pi{width:44px;height:44px;margin-bottom:8px}.wsleakbrief__red3 .wsleakbrief__pi svg{width:22px;height:22px}.wsleakbrief__red3>div{border-color:rgba(233,166,182,.35)}
.wsleakbrief__pog strong{color:#1c1c1c}.wsleakbrief__st,.wsleakbrief__kv li::before{background:#8e666f}.wsleakbrief__tab th{background:#8e666f!important}
.wsleakbrief__ti{background:linear-gradient(135deg,#8e666f,#a7888f);box-shadow:0 6px 14px rgba(142,102,111,.30)}.wsleakbrief__tk{border-color:rgba(233,166,182,.30)}
.wsleakbrief__ime{display:flex;align-items:center;gap:10px}.wsleakbrief__av{flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:#f8e4e9;border:1px solid #e9a6b6;color:#8e666f;font-style:normal;font-weight:800;font-size:14px;display:inline-flex;align-items:center;justify-content:center}
div.wsleakbrief__pog{text-align:center;border:1px solid rgba(233,166,182,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wsleakbrief__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(233,166,182,.22)}div.wsleakbrief__pog>strong,div.wsleakbrief__pog>span:not(.wsleakbrief__pi){display:block}
.wsleakbrief__k--ik .wsleakbrief__kt{text-align:center;padding:28px 20px}
.wsleakbrief__pus{color:#8e666f}.wsleakbrief__plavo{background:#8e666f;margin-top:-72px}.wsleakbrief__k--temna{background:#8e666f}
@media (max-width:860px){.wsleakbrief__s{padding:46px 0}.wsleakbrief__s.wsleakbrief__traka{padding:30px 0}.wsleakbrief__plavo{margin-top:-46px}.wsleakbrief__pog>div{padding:22px 12px}}
